function subscribeCollection<T>(
  col: string,
  mapper: (doc: DocumentSnapshot) => T,
  setter: (items: T[]) => void
) {
  return onSnapshot(collection(db, col), snap => {
    setter(snap.docs.map(d => ({ id: d.id, ...d.data() } as T)));
  });
}
```

