```typescript
export async function ensureFirestoreSeed(db: Firestore) {
  const mainRef = doc(db, 'settings', 'main');
  const snap = await getDoc(mainRef);
  if (snap.exists()) return;
  const batch = writeBatch(db);
  batch.set(mainRef, stripUndefined(seedSettings));
  for (const c of seedCategories) {
    batch.set(doc(db, 'categories', c.id), { name: c.name });
  }
  for (const m of seedMenuItems) {
    batch.set(doc(db, 'menuItems', m.id), stripUndefinedMenuItem(m));
  }
  const d = todayIso();
  batch.set(doc(db, 'dayMenus', d), { date: d, entries: seedDayMenu(d).entries });
  for (const o of seedOrders(d)) {
    batch.set(doc(db, 'orders', o.id), stripUndefinedOrder(o));
  }
  for (const t of seedTasks) {
    batch.set(doc(db, 'tasks', t.id), stripUndefined(t));
  }
  for (const m of seedMailing) {
    batch.set(doc(db, 'mailing', m.id), stripUndefined(m));
  }
  await batch.commit();
}
```

