**Unsubscribe array** on cleanup

```tsx
useEffect(() => {
  const db = getFirebaseDb();
  const unsubs: (() => void)[] = [];
  let alive = true;

  (async () => {
    try {
      await ensureFirestoreSeed(db);
      if (!alive) return;
      setFirebaseReady(true);

      unsubs.push(onSnapshot(doc(db, 'settings', 'main'), (s) => {
        setRemote(prev => ({
          ...prev,
          settings: s.exists() ? mergeSettings(s.data() as object) : seedSettings,
        }));
      }));

      unsubs.push(onSnapshot(collection(db, 'categories'), (snap) => {
        const categories = snap.docs.map(d => ({
          id: d.id,
          name: (d.data() as { name: string }).name,
        }));
        setRemote(prev => ({ ...prev, categories }));
      }));

      unsubs.push(onSnapshot(collection(db, 'menuItems'), (snap) => {
        const menuItems = snap.docs.map(d => {
          const data = d.data() as MenuItem;
          return { ...data, id: d.id };
        });
        setRemote(prev => ({ ...prev, menuItems }));
      }));

      unsubs.push(onSnapshot(collection(db, 'dayMenus'), (snap) => {
        const dayMenus = snap.docs.map(d => d.data() as DayMenu).sort((a,b) => a.date.localeCompare(b.date));
        setRemote(prev => ({ ...prev, dayMenus }));
      }));

      unsubs.push(onSnapshot(collection(db, 'orders'), (snap) => {
        const orders = snap.docs.map(d => ({ ...(d.data() as Order), id: d.id }));
        setRemote(prev => ({ ...prev, orders }));
      }));

      unsubs.push(onSnapshot(collection(db, 'tasks'), (snap) => {
        const tasks = snap.docs.map(d => ({ ...(d.data() as AdminTask), id: d.id }));
        setRemote(prev => ({ ...prev, tasks }));
      }));

      unsubs.push(onSnapshot(collection(db, 'mailing'), (snap) => {
        const mailingList = snap.docs.map(d => ({ ...(d.data() as MailingEntry), id: d.id }));
        setRemote(prev => ({ ...prev, mailingList }));
      }));
    } catch (e) {
      toast.error(...);
    }
  })();

  return () => {
    alive = false;
    unsubs.forEach(u => u());
  };
}, []);
```

